mapper.insert:
INSERT INTO schedule_assignment (
    plan_id, activity_id, area_id, position_id, user_id, work_date,
    start_time, end_time, assignment_status
) VALUES (
    #{planId}, #{activityId}, #{areaId}, #{positionId}, #{userId}, #{workDate},
    #{startTime}, #{endTime}, #{assignmentStatus}
)

mapper.update:
UPDATE schedule_assignment
SET assignment_status = #{assignmentStatus}
WHERE id = #{id}
  AND is_deleted = 0

mapper.select:
SELECT COUNT(1)
FROM schedule_assignment
WHERE activity_id = #{activityId}
  AND user_id = #{userId}
  AND work_date = #{workDate}
  AND is_deleted = 0
  AND start_time < #{endTime}
  AND #{startTime} < end_time
